/*
 * Pro tips
 * - Sorting reveals the only differences you need to compare: adjacent gaps.
 * - Handle size <= 2 before indexing elements 0 and 1.
 * - Use one common difference and reject the first different gap; repeated equal values can have difference zero.
 * - This sorts the input in place. With int extremes, compute gaps using long to avoid overflow.
 * - Complexity: O(n log n) time; the Java list sort may use O(n) auxiliary space.
 */

import java.util.Arrays;
import java.util.List;
import java.util.Scanner;
import java.util.stream.Collectors;

class Solution {
    public static boolean canMakeArithmeticProgression(List<Integer> arr) {
        if (arr.size() <= 2) {
            return true;
        }

        arr.sort(null);

        int diff = arr.get(1) - arr.get(0);
        for (int i = 2; i < arr.size(); i++) {
            if (arr.get(i) - arr.get(i - 1) != diff) {
                return false;
            }
        }

        return true;
    }

    public static List<String> splitWords(String s) {
        return s.isEmpty() ? List.of() : Arrays.asList(s.split(" "));
    }

    public static void main(String[] args) {
        java.util.Scanner scanner = new java.util.Scanner(System.in);
        List<Integer> arr = splitWords(scanner.nextLine()).stream().map(Integer::parseInt).collect(Collectors.toList());
        scanner.close();
        boolean res = canMakeArithmeticProgression(arr);
        System.out.println(res);
    }
}
